#!/usr/bin/env python3
"""The check for regression-test/t1. Generated by eval/build_tasks.py; run it
as `python3 check.py <workspace>`. Exit 0 is a pass."""

import json
import re
import shutil
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[3]))
from checklib import CAMEL, SNAKE, main  # noqa: E402


def check(ws):
    ws.check("./dev test passes", *ws.dev("test"))
    ws.check("the task's own assertions", *ws.py('import datetime as d\nfrom tally.dates import add_months\nassert add_months(d.date(2023, 1, 31), 1) == d.date(2023, 2, 28)\nassert add_months(d.date(2024, 5, 31), -3) == d.date(2024, 2, 29)\nassert add_months(d.date(2024, 12, 15), 1) == d.date(2025, 1, 15)', env=None))

    found = sorted(p for p in (ws.source / "tests").rglob("test*.py") if re.search(r"tal[_-]?2291(?!\d)", p.name, re.I))
    ws.signals["followed"] = bool(found)
    ws.check("rule: a regression test named after TAL-2291", bool(found), "no tests/regressions/test_tal_2291.py")
    if found:
        modules = []
        for p in found:
            rel = p.relative_to(ws.source)
            (ws.root / rel).parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(p, ws.root / rel)
            for parent in rel.parents:
                if parent.parts and not (ws.root / parent / "__init__.py").exists():
                    (ws.root / parent / "__init__.py").touch()
            modules.append(".".join(rel.with_suffix("").parts))
        ok, out = ws.run([sys.executable, "-m", "unittest", *modules])
        ws.check("rule: the regression test passes with the fix", ok, out)
        shutil.copy2(ws.task / "setup" / 'tally/dates.py', ws.root / 'tally/dates.py')
        ok, out = ws.run([sys.executable, "-m", "unittest", *modules])
        ws.check("rule: the regression test fails without the fix", not ok, "it still passes with the bug put back")


if __name__ == "__main__":
    main(check)
